node.script:
function SetActorAndChildrenStatic(so_self, is_static)
{
	Actor_SetActorFlag(so_self, "STATIC", is_static);
	local num_children = StageObject_GetNumberOfChildren(so_self);
	for (local i = 0; i < num_children; i++)
	{
		local so = StageObject_GetChildByIndex(so_self, i);
		if (StageObject_GetType(so) == STAGE_OBJECT_TYPE_ACTOR)
		{
			Actor_SetActorFlag(so, "STATIC", is_static);
		}
	}
}

function OnStart(so_self, length)
{
	StageObject_SetKeyValueFloat(so_self, "base_z", StageObject_GetPosition(so_self)[2]);
	SetActorAndChildrenStatic(so_self, false);

}

function OnUpdate(so_self, time_key, length)
{
	local pos = StageObject_GetPosition(so_self);

	if (pos == null)
		return;

	local base_z = StageObject_GetKeyValue(so_self, "base_z");
	local target_z = StageObject_GetKeyValue(so_self, "target_z");
	local lower_amount = target_z-base_z;
	StageObject_SetPosition(so_self, pos[0], pos[1], base_z + lower_amount * time_key / length);
}

function OnEnd(so_self, length)
{
	SetActorAndChildrenStatic(so_self, true);

}

node.interaction_0_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	//Actor_PlayAnimation(so_self, "move");

	local speed = StageObject_GetKeyValue(so_self,"speed");
	Actor_PlayAnimationWithDelayPlaybackSpeedAndPosition(so_self, "move", 0, speed, 0);


	StageObject_SetKeyValueBoolean(so_self, "moved", true);
}

